def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    """For each area and its distance in km, return the delivery fee in shillings, or -1 if not delivered to."""
    result = {}
    for area, distance_km in areas_km.items():
        distance_m = int(distance_km * 1000)
        zone = zone_of(area)
        if zone == "X":
            result[area] = -1
        else:
            result[area] = delivery_fee_kes(distance_m)
    return result
```

