def party_packs(menu: list[str], guests: int) -> int:
    """How many 500g market packs to buy for a party with given menu codes."""
    total_grams = 0
    for code in menu:
        if code not in PRICE_CENTS:
            raise ValueError(f"Unknown menu code: {code}")
        total_grams += GRAMS_PER_GUEST[code] * guests
    # Round up to nearest 500g pack
    return -(-total_grams // 500)
```

